def _on_clear_background(self):
    """清空所有后台监听项的匹配计数和状态"""
    count = 0
    for p in self._items:
        if p.get("persistent"):
            p["match_count"] = 0
            count += 1
    if count:
        self._log(f"[清空后台] 已清除 {count} 个后台项的匹配计数")
        self._refresh_table()
        self._auto_save()
        self._update_bg_status()
    else:
        QMessageBox.information(self, "提示", "当前没有后台监听项")

