def _on_move_up(self):
    row = self.table.currentRow()
    if row > 0:
        self._items[row], self._items[row - 1] = self._items[row - 1], self._items[row]
        self._refresh_table()
        self.table.selectRow(row - 1)
        self._auto_save()

