def get_byte_description(offset: int, result: dict) -> str:
    """获取字节位置说明"""
    # 帧头
    if offset == 0:
        return "帧起始字符(0x68)"

    # 长度域
    if offset in [1, 2]:
        return "长度域(2字节)"

    # 控制域
    if offset == 3:
        return "控制域"

    # 根据用户数据区长度计算
    if "用户数据区" in result:
        user_data_start = 4
        user_data_len = result["用户数据区"].get("长度", 0)

        if user_data_start <= offset < user_data_start + user_data_len:
            rel_offset = offset - user_data_start

            # 地址域 (12字节)
            if "地址域" in result["用户数据区"]:
                if rel_offset < 12:
                    if rel_offset < 6:
                        return f"源地址[{rel_offset}]"
                    else:
                        return f"目的地址[{rel_offset-6}]"
                rel_offset -= 12

            # AFN
            if rel_offset == 0:
                return "应用功能码(AFN)"

            # SEQ
            if rel_offset == 1:
                return "帧序列号(SEQ)"

            # DI (4字节)
            if 2 <= rel_offset < 6:
                di_pos = ["DI0", "DI1", "DI2", "DI3"][rel_offset - 2]
                return f"数据标识({di_pos})"

            # 数据内容
            if rel_offset >= 6:
                return f"数据内容[{rel_offset-6}]"

        # 校验和
        cs_offset = user_data_start + user_data_len
        if offset == cs_offset:
            return "校验和(CS)"

        # 结束符
        if offset == cs_offset + 1:
            return "结束符(0x16)"

    return ""

    self._stopbits = stopbits

def open_port(self) -> bool:
    """打开串口，成功返回 True"""
    if self._ser and self._ser.is_open:
        return True
    try:
        parity_map = {"无": "N", "偶": "E", "奇": "O"}
        parity_val = parity_map.get(self._parity, self._parity)
        self._ser = serial.Serial(
            port=self._port,
            baudrate=self._baudrate,
            bytesize=self._bytesize,
            parity=parity_val,
            stopbits=self._stopbits,
            timeout=0.1,
        )
        self._running = True
        if not self.isRunning():
            self.start()
        self.connection_changed.emit(True)
        self.log_message.emit(f"[串口] 已打开 {self._port} @ {self._baudrate}")
        return True
    except serial.SerialException as e:
        self.error_occurred.emit(f"打开串口失败: {e}")
        return False

def close_port(self):

        return False

def close_port(self):
    """关闭串口"""
    self._running = False
    if self._ser and self._ser.is_open:
        try:
            self._ser.close()
        except Exception:
            pass
    self._ser = None
    self.connection_changed.emit(False)
    self.log_message.emit("[串口] 已关闭")

def is_open(self) -> bool:

    self.log_message.emit("[串口] 已关闭")

def is_open(self) -> bool:
    return self._ser is not None and self._ser.is_open

def send_frame(self, frame_bytes: bytes) -> bool:

    return self._ser is not None and self._ser.is_open

def send_frame(self, frame_bytes: bytes) -> bool:
    """发送一帧字节数据"""
    if not self._ser or not self._ser.is_open:
        self.error_occurred.emit("串口未打开")
        return False
    try:
        self._ser.write(frame_bytes)
        hex_str = frame_bytes.hex().upper()
        formatted = " ".join(hex_str[i:i+2] for i in range(0, len(hex_str), 2))
        self.log_message.emit(f"[发送] {formatted}")
        return True
    except serial.SerialException as e:
        self.error_occurred.emit(f"发送失败: {e}")
        return False

def send_hex_string(self, hex_str: str) -> bool:

        return False

def send_hex_string(self, hex_str: str) -> bool:
    """发送十六进制字符串（自动去除空格）"""
    clean = hex_str.replace(" ", "").strip()
    if not clean:
        return False
    try:
        data = bytes.fromhex(clean)
        return self.send_frame(data)
    except ValueError as e:
        self.error_occurred.emit(f"发送数据格式错误: {e}")
        return False

def run(self):

        return False

def run(self):
    """后台读取循环"""
    while self._running and self._ser and self._ser.is_open:
        try:
            if self._ser.in_waiting:
                raw = self._ser.read(self._ser.in_waiting)
                self._buffer.extend(raw)
                self._process_buffer()
            else:
                time.sleep(0.01)
        except serial.SerialException:
            break
        except Exception as e:
            self.log_message.emit(f"[串口错误] 接收循环异常: {e}")
    self._running = False
    if self._ser and self._ser.is_open:
        try:
            self._ser.close()
        except Exception:
            pass
    self._ser = None
    self.connection_changed.emit(False)

