def get_supported_di_keys(self) -> List[Tuple[int, int, int, int]]:
    """返回当前支持的DI键列表（来自DI_FIELD_SCHEMA）"""
    return list(DI_FIELD_SCHEMA.keys())

def get_di_schema(self, di_key: Tuple[int, int, int, int]) -> Optional[Dict[str, Any]]:

    return list(DI_FIELD_SCHEMA.keys())

def get_di_schema(self, di_key: Tuple[int, int, int, int]) -> Optional[Dict[str, Any]]:
    """获取指定DI的字段Schema"""
    return DI_FIELD_SCHEMA.get(di_key)

def generate_data(self, di_key: Tuple[int, int, int, int], field_values: Dict[str, Any]) -> bytes:

    return DI_FIELD_SCHEMA.get(di_key)

def generate_data(self, di_key: Tuple[int, int, int, int], field_values: Dict[str, Any]) -> bytes:
    """根据DI字段Schema和字段值生成用户数据区字节流

    Args:
        di_key: DI四元组 (di3, di2, di1, di0)
        field_values: 字段名 -> 值的字典

    Returns:
        打包后的用户数据区字节
    """
    schema = DI_FIELD_SCHEMA.get(di_key)
    if not schema:
        raise ValueError(f"不支持的DI组合: {di_key}")

    fields = schema["fields"]
    values: Dict[str, Any] = {}

    # 第一遍：收集所有字段值（含默认值）
    for field in fields:
        name = field["name"]
        val = field_values.get(name, field.get("default"))
        if val is None:
            if field.get("required", False):
                raise ValueError(f"缺少必填字段: {name}")
            continue
        values[name] = val
        # 同时收集子字段值（用于sub_fields合并计算）
        for sub in field.get("sub_fields", []):
            sub_name = sub["name"]
            if sub_name in field_values:
                values[sub_name] = field_values[sub_name]

    # 第二遍：处理 count_field 引用（列表字段需自动计算数量并回填）
    for field in fields:
        name = field["name"]
        if field.get("type") == "list" and "count_field" in field:
            ref_name = field["count_field"]
            items = values.get(name, [])
            values[ref_name] = len(items) if isinstance(items, list) else 0

    # 第三遍：处理 sub_fields（子字段合并为父字段值，需在length_field之前）
    for field in fields:
        name = field["name"]
        if "sub_fields" in field:
            parent_type = field["type"]
            if parent_type in ("uint8", "enum", "uint16", "uint32"):
                parent_val = 0
                for sub in field["sub_fields"]:
                    if not self._check_condition(sub, values):
                        continue
                    sub_name = sub["name"]
                    sub_val = values.get(sub_name, sub.get("default", 0))
                    bit_width = sub.get("bit_width", 1)
                    bit_offset = sub.get("bit_offset", 0)
                    mask = (1 << bit_width) - 1
                    parent_val |= (int(sub_val) & mask) << bit_offset
                values[name] = parent_val
            elif parent_type == "bytes":
                parent_val = ""
                for sub in field["sub_fields"]:
                    if not self._check_condition(sub, values):
                        continue
                    sub_name = sub["name"]
                    sub_val = values.get(sub_name, sub.get("default", ""))
                    sub_type = sub.get("type", "bytes")
                    if sub_type in ("uint8", "enum"):
                        parent_val += f"{int(sub_val):02X}"
                    elif sub_type == "bytes":
                        parent_val += str(sub_val)
                    elif sub_type in ("uint16", "uint32"):
                        endian = sub.get("endian", "big")
                        fmt = ">H" if endian == "big" else "<H"
                        if sub_type == "uint32":
                            fmt = ">I" if endian == "big" else "<I"
                        parent_val += struct.pack(fmt, int(sub_val)).hex()
                values[name] = parent_val

    # 第四遍：处理 length_field 引用（变长字段需提前计算长度并回填）
    for field in fields:
        name = field["name"]
        if "length_field" in field:
            ref_name = field["length_field"]
            val = values.get(name)
            if val is not None:
                raw_len = len(self._to_raw_bytes(field, val))
                offset = field.get("length_offset", 0)
                values[ref_name] = raw_len + offset

    # 第五遍：按顺序打包所有字段
    result = b""
    for field in fields:
        name = field["name"]
        val = values.get(name)
        if val is None and field.get("optional", False):
            continue
        result += self._pack_field(field, val)

    return result

