# ------------------- 内部打包工具方法 -------------------

def _check_condition(self, field: Dict[str, Any], values: Dict[str, Any]) -> bool:
    """检查字段条件是否满足（用于条件显示/打包的字段）"""
    cond = field.get("condition")
    if not cond:
        return True
    ref_name = cond.get("field")
    ref_val = values.get(ref_name)
    target_val = cond.get("value")
    op = cond.get("eval", "eq")
    if op == "eq":
        return ref_val == target_val
    elif op == "ne":
        return ref_val != target_val
    return True

def _pack_field(self, field: Dict[str, Any], value: Any) -> bytes:

    return True

def _pack_field(self, field: Dict[str, Any], value: Any) -> bytes:
    """根据字段Schema将单个值打包为字节"""
    if value is None:
        return b""

    ftype = field["type"]

    if ftype in ("uint8", "enum"):
        return struct.pack("B", int(value))

    elif ftype == "uint16":
        endian = field.get("endian", "little")
        fmt = ">H" if endian == "big" else "<H"
        return struct.pack(fmt, int(value))

    elif ftype == "uint32":
        endian = field.get("endian", "little")
        fmt = ">I" if endian == "big" else "<I"
        return struct.pack(fmt, int(value))

    elif ftype == "bytes":
        if isinstance(value, str):
            value = bytes.fromhex(value.replace(" ", ""))
        if field.get("reverse"):
            value = value[::-1]
        if "length" in field:
            length = field["length"]
            if len(value) < length:
                value = value + b"\x00" * (length - len(value))
            elif len(value) > length:
                value = value[:length]
        return value

    elif ftype == "ascii":
        data = value.encode("ascii", errors="ignore")
        length = field.get("length")
        if length:
            data = data[:length].ljust(length, b"\x00")
        return data

    elif ftype == "bcd":
        if isinstance(value, str):
            data = bytes.fromhex(value.replace(" ", ""))
        else:
            data = bytes(value)
        length = field.get("length")
        if length:
            if len(data) < length:
                data = data + b"\x00" * (length - len(data))
            elif len(data) > length:
                data = data[:length]
        return data

    elif ftype == "list":
        item_fields = field["item_fields"]
        items = value if isinstance(value, list) else []

        # 打包数量前缀（仅当使用 count_type 时；count_field 由外部字段负责）
        if "count_type" in field:
            count_type = field["count_type"]
            if count_type == "uint8":
                data = struct.pack("B", len(items))
            elif count_type == "uint16":
                data = struct.pack(">H", len(items))
            else:
                data = b""
        else:
            data = b""

        # 打包每一项
        for item in items:
            for item_field in item_fields:
                item_name = item_field["name"]
                item_val = item.get(item_name, item_field.get("default"))
                data += self._pack_field(item_field, item_val)
        return data

    else:
        raise ValueError(f"不支持的字段类型: {ftype}")

def _to_raw_bytes(self, field: Dict[str, Any], value: Any) -> bytes:

        raise ValueError(f"不支持的字段类型: {ftype}")

def _to_raw_bytes(self, field: Dict[str, Any], value: Any) -> bytes:
    """将值转换为原始字节（不计算固定长度填充），用于length_field长度计算"""
    if value is None:
        return b""

    ftype = field["type"]
    if ftype == "bytes":
        if isinstance(value, str):
            value = bytes.fromhex(value.replace(" ", ""))
        if field.get("reverse"):
            value = value[::-1]
        return value

    elif ftype == "ascii":
        return value.encode("ascii", errors="ignore")

    elif ftype == "bcd":
        if isinstance(value, str):
            return bytes.fromhex(value.replace(" ", ""))
        return bytes(value)

    else:
        # 其他类型使用标准打包（uint/enum/list等长度固定或可预期）
        return self._pack_field(field, value)

    self.data = data

def calculate_checksum(self, data: bytes) -> int:
    """计算校验和 - 八位位组算术和"""
    return sum(data) & 0xFF
def frame_pack(self) -> bytes:
