def _get_di_key(self, user_data: dict) -> tuple:
    """获取 DI 的键"""
    if "数据标识 (DI)" not in user_data:
        return None

    di = user_data["数据标识 (DI)"]
    if "整数值" in di:
        di_int = int(di["整数值"], 16) if isinstance(di["整数值"], str) else di["整数值"]
        # 从 DI 组合映射中找到对应的键
        di3 = (di_int >> 24) & 0xFF
        di2 = (di_int >> 16) & 0xFF
        di1 = (di_int >> 8) & 0xFF
        di0 = di_int & 0xFF
        return (di3, di2, di1, di0)
    return None

