            "单位": "毫秒"
        }
    }
    # PLUZ扩展：包含报文长度字段
    if len(data) >= 10:
        msg_len = int.from_bytes(data[8:10], 'little')
        result["报文长度"] = {"原始值": data[8:10].hex().upper(), "十进制": msg_len}
    return result

