    return result

def _parse_query_task_timeout_data(self, data: bytes) -> Dict[str, Any]:
    """解析查询/返回任务建议超时时间（E8 00 03 0B）
    下行查询：无数据；上行应答：4×2字节 BIN 小端（优先级0~3的超时时间）
    """
    if len(data) < 8:
        return {"说明": "查询命令，无数据内容"}
    result = {}
    for i in range(4):
        offset = i * 2
        timeout = int.from_bytes(data[offset:offset+2], 'little')
