                file_paths[key] = str(rel)
            except ValueError:
                file_paths[key] = str(path)
    config["file_paths"] = file_paths

    try:
        with open(self._config_path, "w", encoding="utf-8") as f:
            json.dump(config, f, ensure_ascii=False, indent=2)
    except Exception as e:
        print(f"[配置保存失败] {e}")

