def Sub_33(bytes_string):
    tempbytes = bytes(0)
    for byte1 in bytes_string:
        if byte1 >= 0x33:
            tempbytes +=  (byte1 - 0x33).to_bytes(1, "little")
        else:
            tempbytes  += (byte1+256-0x33).to_bytes(1, "little")
    return tempbytes

