def _calculate_fcs(self, data: bytes) -> int:
    """
    计算FCS/HCS校验和
    使用CCITT-CRC16多项式: x^16 + x^12 + x^5 + 1 (0x8408)
    """
    crc = 0xFFFF
    for byte in data:
        crc ^= byte
        for _ in range(8):
            if crc & 0x0001:
                crc = (crc >> 1) ^ 0x8408
            else:
                crc >>= 1
    return crc ^ 0xFFFF

