def to_byte(self) -> int:

    self.dir = dir

def to_byte(self) -> int:
    """将控制域转换为单字节整数值"""
    return (self.dir << 7) | (self.prm << 6) | (self.comm_type & 0x3F)

@classmethod

@classmethod
def from_byte(cls, byte_val: int) -> "GDWControlField":
    """从单字节整数值解析控制域"""
    return cls(
        comm_type=byte_val & 0x3F,
        prm=(byte_val >> 6) & 0x01,
        dir=(byte_val >> 7) & 0x01,
    )

