    if PresetButtonManager.add_command(self.protocol_mode, result):
        QMessageBox.information(
            self, "成功",
            f"已添加预设按钮：{result['button_name']}\n分组：{result['group_name']}"
        )
        self.preset_added.emit(self.protocol_mode, frame_hex, result["config"])
    else:
