@staticmethod

@staticmethod
def check_frame(data: bytes) -> bool:
    if len(data) < 12:
        return False
    if data[0] != 0x68 or data[7] != 0x68 or data[-1] != 0x16:
        return False
    cs = sum(data[0:-2]) & 0xFF
    return cs == data[-2]

