def _find_address_end(self, data: bytes) -> int:
    """查找地址域结束位置（地址域最高位为1表示结束）"""
    if len(data) < 3:
        return -1
    pos = 2  # 从第3字节开始（跳过起始标志和格式域）
    for i in range(pos, min(pos + 8, len(data))):
        if data[i] & 0x01:  # 最高位为1表示地址域结束
            return i + 1
    return -1

@property
