def _format_hex(self, hex_str: str) -> str:
    """格式化 HEX 字符串（添加空格分隔）"""
    if not hex_str:
        return ""
    clean = hex_str.replace(" ", "").upper()
    return " ".join(clean[i:i+2] for i in range(0, len(clean), 2))

