def _parse_frame(self, frame: bytes, protocol: str) -> Optional[List]:
    """解析帧"""
    parser = self._parsers.get(protocol)
    if parser and hasattr(parser, 'parse_to_table'):
        try:
            return parser.parse_to_table(frame)
        except Exception:
            pass
    return None

